-- Golden set v1 · archivo 1 de 2: limpieza, usuarios y las 15 necesidades.
-- Antes: `supabase db reset` y cargar en Vault motor_webhook_url y motor_webhook_secret. n8n con el workflow del motor activo.
-- Después: esperar en n8n las 15 ejecuciones (terminan sin candidatos) y recién ahí correr el archivo 2.
-- Datos de prueba de dirección: no se editan. IDs: 0000…1NNN = N-NN, 0000…2NNN = D-NN.

begin;

-- 1. Limpieza: la base queda sólo con el golden set. La demo vuelve con el próximo `supabase db reset`.
delete from public.juicios;
delete from public.imagenes_publicacion;
delete from public.publicaciones;
delete from auth.users where email like '%@golden.vaiven.dev';

